import Domain
import Foundation
import GRDB
@testable import MLInfrastructure
import Testing

// MARK: - Helpers

private func makeStorage() async throws -> GRDBStorageActor {
    try GRDBStorageActor(databasePath: nil)
}

private func makeMetrics(
    modelId: String = "test-model",
    ts: Double = 1000
) -> InferenceMetrics {
    InferenceMetrics(
        modelId: ModelID(modelId),
        audioDuration: 60.0,
        inferenceDuration: 0.5,
        realTimeFactor: 120.0,
        confidence: 0.9,
        sampleCount: 960_000,
        computeUnit: .cpuAndNeuralEngine,
        timestamp: Date(timeIntervalSince1970: ts)
    )
}

// MARK: - Test Suite

@Suite("InferenceTelemetry.flushToStorage", .serialized)
struct InferenceTelemetryFlushTests {

    @Test("INV-002: successful flush leaves recentMetrics empty")
    func flushClearsBufferOnSuccess() async throws {
        let telemetry = InferenceTelemetry()
        await telemetry.record(makeMetrics(ts: 1000))
        await telemetry.record(makeMetrics(ts: 1001))
        await telemetry.record(makeMetrics(ts: 1002))

        let storage = try await makeStorage()
        try await telemetry.flushToStorage(storage)

        let remaining = await telemetry.recentMetrics(limit: 1000)
        #expect(remaining.isEmpty, "Buffer must be empty after successful flush (INV-002)")
    }

    @Test("IDEM-002: flush on empty buffer completes without error")
    func flushEmptyBufferIsNoOp() async throws {
        let telemetry = InferenceTelemetry()
        let storage = try await makeStorage()
        try await telemetry.flushToStorage(storage)

        let remaining = await telemetry.recentMetrics(limit: 1000)
        #expect(remaining.isEmpty, "Buffer must stay empty after no-op flush (IDEM-002)")
    }

    @Test("LIVE-001: all flushed entries are queryable in inference_telemetry")
    func flushWritesAllEntriesToStorage() async throws {
        let telemetry = InferenceTelemetry()
        await telemetry.record(makeMetrics(ts: 3000))
        await telemetry.record(makeMetrics(ts: 3001))
        await telemetry.record(makeMetrics(ts: 3002))

        let storage = try await makeStorage()
        try await telemetry.flushToStorage(storage)

        let count = try await storage.dbPool.read { db in
            try Int.fetchOne(db, sql: "SELECT COUNT(*) FROM inference_telemetry") ?? 0
        }
        #expect(count == 3, "Expected 3 rows in inference_telemetry after flush, got \(count) (LIVE-001)")
    }
}

